-- O H2 gera os IDs automaticamente com GENERATED BY DEFAULT AS IDENTITY.
CREATE TABLE IF NOT EXISTS usuarios (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo VARCHAR(20) NOT NULL,
    nome VARCHAR(200) NOT NULL,
    email VARCHAR(254) NOT NULL UNIQUE,
    senha VARCHAR(255) NOT NULL,
    perfil VARCHAR(20) NOT NULL,
    matricula VARCHAR(50) UNIQUE,
    curso VARCHAR(200),
    departamento VARCHAR(200)
);

CREATE TABLE IF NOT EXISTS materiais (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo VARCHAR(10) NOT NULL,
    titulo VARCHAR(255) NOT NULL,
    autor VARCHAR(200) NOT NULL,
    isbn VARCHAR(30) NOT NULL,
    licencas_totais INT,
    licencas_em_uso INT
);

CREATE TABLE IF NOT EXISTS exemplares (
    codigo VARCHAR(50) PRIMARY KEY,
    livro_id BIGINT NOT NULL REFERENCES materiais(id),
    emprestado BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS emprestimos (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo VARCHAR(10) NOT NULL,
    leitor_id BIGINT NOT NULL REFERENCES usuarios(id),
    material_id BIGINT NOT NULL REFERENCES materiais(id),
    exemplar_codigo VARCHAR(50) REFERENCES exemplares(codigo),
    data_inicio DATE NOT NULL,
    data_prevista DATE NOT NULL,
    data_encerramento DATE,
    status VARCHAR(15) NOT NULL
);

CREATE TABLE IF NOT EXISTS multas (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    emprestimo_id BIGINT NOT NULL REFERENCES emprestimos(id),
    valor DECIMAL(12, 2) NOT NULL,
    dias_atraso INT NOT NULL,
    status VARCHAR(10) NOT NULL
);

CREATE TABLE IF NOT EXISTS reservas_material (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    leitor_id BIGINT NOT NULL REFERENCES usuarios(id),
    material_id BIGINT NOT NULL REFERENCES materiais(id),
    data_solicitacao TIMESTAMP NOT NULL,
    posicao_fila INT NOT NULL,
    prazo_retirada TIMESTAMP,
    status VARCHAR(15) NOT NULL
);

CREATE TABLE IF NOT EXISTS salas_estudo (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    identificacao VARCHAR(100) NOT NULL UNIQUE,
    capacidade INT NOT NULL,
    tempo_maximo_permanencia INT NOT NULL,
    status VARCHAR(15) NOT NULL DEFAULT 'LIVRE'
);

CREATE TABLE IF NOT EXISTS equipamentos (
    sala_id BIGINT NOT NULL REFERENCES salas_estudo(id),
    nome VARCHAR(100) NOT NULL,
    disponivel BOOLEAN NOT NULL,
    PRIMARY KEY (sala_id, nome)
);

CREATE TABLE IF NOT EXISTS horarios_sala (
    sala_id BIGINT NOT NULL REFERENCES salas_estudo(id),
    inicio TIME NOT NULL,
    fim TIME NOT NULL,
    PRIMARY KEY (sala_id, inicio, fim)
);

CREATE TABLE IF NOT EXISTS reservas_sala (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    leitor_id BIGINT NOT NULL REFERENCES usuarios(id),
    sala_id BIGINT NOT NULL,
    data DATE NOT NULL,
    horario_inicio TIME NOT NULL,
    horario_fim TIME NOT NULL,
    hora_check_in TIME,
    hora_check_out TIME,
    status VARCHAR(15) NOT NULL,
    FOREIGN KEY (sala_id, horario_inicio, horario_fim) REFERENCES horarios_sala(sala_id, inicio, fim)
);
